import { useQuery, QueryClient } from '@tanstack/react-query';

// Pre-seed the cache with initial data
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      initialData: () => {
        const cached = localStorage.getItem('users');
        return cached ? JSON.parse(cached) : undefined;
      },
    },
  },
});

function UserList() {
  const { data, isLoading } = useQuery({
    queryKey: ['users'],
    queryFn: async () => {
      const res = await fetch('/api/users');
      return res.json();
    },
  });

  // data is available instantly from initialData!
  // isLoading is true, but the UI renders with the placeholder
  return (
    <ul>
      {data?.map(user => <li key={user.id}>{user.name}</li>)}
    </ul>
  );
}

import { useState } from 'react';
import { useQuery, keepPreviousData } from '@tanstack/react-query';

function PaginatedUsers() {
  const [page, setPage] = useState(1);

  const { data, isLoading, isPlaceholderData } = useQuery({
    queryKey: ['users', page],
    queryFn: () => fetchUsersPage(page),
    placeholderData: keepPreviousData,
  });

  return (
    <div>
      <ul>
        {data?.users.map(user => (
          <li key={user.id}>{user.name}</li>
        ))}
      </ul>
      <button
        onClick={() => setPage(p => p - 1)}
        disabled={page === 1 || isLoading}
      >
        Previous
      </button>
      <button
        onClick={() => setPage(p => p + 1)}
        disabled={!data?.hasMore || isPlaceholderData}
      >
        {isPlaceholderData ? 'Loading...' : 'Next'}
      </button>
      {isPlaceholderData && (
        <p className="muted">Loading next page...</p>
      )}
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';

function ArticleList({ categoryId }: { categoryId: string }) {
  const { data, isLoading, isPlaceholderData } = useQuery({
    queryKey: ['articles', categoryId],
    queryFn: () => fetchArticles(categoryId),
    initialData: () => {
      // Pre-loaded from SSR â€” instant first paint
      return window.__INITIAL_ARTICLES?.[categoryId];
    },
    placeholderData: (previousData) => {
      // If cache was cleared, show old data while refetching
      return previousData;
    },
  });

  return (
    <div>
      {isLoading && <p>Loading articles...</p>}
      {isPlaceholderData && (
        <span className="badge">Updating...</span>
      )}
      {data?.map(article => (
        <article key={article.id}>
          <h3>{article.title}</h3>
        </article>
      ))}
    </div>
  );
}
